package objeto.orientacao.exercise.test;import jdk.jshell.SourceCodeAnalysis;import objeto.orientacao.exercise.domain.Funcionario;import java.util.Scanner;public class FuncionarioTest01{    public static void main(String[] args) {        Funcionario funcionario01 = new Funcionario();        Scanner input = new Scanner(System.in);        System.out.println("Nome: ");        funcionario01.nome = input.nextLine();        System.out.println("Idade: ");        funcionario01.idade = input.nextInt();        for (int i = 0; i <= 3; i++){            System.out.printf("Salario%d: ", i);            funcionario01.salario[i] = input.nextFloat();            float salarios = 0;            salarios += funcionario01.salario[i];            float mediaSalario = (salarios) / 3;            System.out.println(mediaSalario);        }    }}